  \foreach \x in {1.2,3.6,6.0} \node[gridnode] at (\x,3.2) {};
  \node[mlabel, anchor=south] at (1.2,3.42) {$\varphi_{i-1}^{n+1}$};
  \node[mlabel, anchor=south] at (3.6,3.42) {$\varphi_{i}^{n+1}$};
  \node[mlabel, anchor=south] at (6.0,3.42) {$\varphi_{i+1}^{n+1}$};

  % 控制体界面：虚线刻线，界面物性在此取算术平均
