    parser.add_argument("fig_dir", nargs="?", default="figures", type=Path)
    parser.add_argument("--paper", type=Path, default=Path("paper"))
    parser.add_argument("--referenced-only", action="store_true", help="最终编译仅检查活跃源码实际引用的图")
