    if warnings:
        print(f"  OK: 可确定的图 PDF 检查通过；另有 {len(warnings)} 项需复核，不能视为全部视觉合格")
    else:
        print("  OK: 图 PDF 字体嵌入、最终印刷字号、文字边界、留白和对比度检查通过")
    return 0


